python3 /dev/stdin << 'PYEOF'
import re

with open('/home/akash/Desktop/Akash/Projects/Agentic-Workflow-Design/software/mcfm/src/Mods/pp_mod.f90', 'r') as f:
    content = f.read()

lines = content.split('\n')
start = -1
end_line = -1
for i, line in enumerate(lines):
    if 'reshape' in line and '(/' in line:
        start = i + 1
    if '/ 9,9,9,9' in line or ',9,9,9,9' in line:
        end_line = i
        break

data_lines = lines[start:end_line]
all_nums = []
for dl in data_lines:
    dl2 = dl.replace('&', '').strip()
    dl2 = re.sub(r'/\).*', '', dl2).strip()
    if dl2:
        parts = [n.strip() for n in dl2.split(',') if n.strip()]
        for p in parts:
            try:
                all_nums.append(int(p))
            except:
                pass

assert len(all_nums) == 6561, f"Got {len(all_nums)} numbers"

# Format for C++ in rows of 27 values each
rows = []
for i in range(0, len(all_nums), 27):
    row_vals = all_nums[i:i+27]
    row_str = '    ' + ', '.join(str(x) for x in row_vals) + ','
    rows.append(row_str)
rows[-1] = rows[-1].rstrip(',')

cpp_init_data = '\n'.join(rows)

# Write pp_mod.hpp
hpp_content = """#ifndef PP_MOD_HPP
#define PP_MOD_HPP

#include <ppmax_mod.hpp>

namespace pp_mod {
    using namespace ppmax_mod;
    extern int pp[6561];
}

#endif // PP_MOD_HPP
"""

# Write pp_mod.cpp
cpp_content = f"""#include <pp_mod.hpp>

// pp(-4:4,-4:4,-4:4,-4:4) stored in Fortran column-major order.
// Flat index: (i+4) + 9*(j+4) + 81*(k+4) + 729*(l+4)
// where i,j,k,l each range from -4 to 4.
namespace pp_mod {{
    int pp[6561] = {{
{cpp_init_data}
    }};
}}

extern "C" {{
    int* pp_mod_pp() {{ // @coverage-probe
        return pp_mod::pp;
    }}
}}
"""

# Write Fortran shim pp_mod.f90
f90_content = """module pp_mod
  use, intrinsic :: iso_c_binding
  use ppmax_mod, only: ppmax
  implicit none

  private
    interface
      function get_pp() bind(C, name="pp_mod_pp")
        import :: c_ptr, c_int
        type(c_ptr) :: get_pp
      end function get_pp
    end interface

    integer(c_int), pointer :: pp_flat(:) => null()

  public :: ppmax, pp, pp_mod_init, pp_mod_finalize

  integer(c_int), pointer :: pp(:,:,:,:) => null()

contains
  subroutine pp_mod_init()
    implicit none
    call c_f_pointer(get_pp(), pp_flat, [9*9*9*9])
    pp(-4:4,-4:4,-4:4,-4:4) => pp_flat
  end subroutine pp_mod_init

  subroutine pp_mod_finalize()
    implicit none
    nullify(pp_flat)
    nullify(pp)
  end subroutine pp_mod_finalize

end module pp_mod
"""

with open('/tmp/pp_mod.hpp', 'w') as f:
    f.write(hpp_content)
with open('/tmp/pp_mod.cpp', 'w') as f:
    f.write(cpp_content)
with open('/tmp/pp_mod.f90', 'w') as f:
    f.write(f90_content)

print("Files written to /tmp/")
print(f"HPP length: {len(hpp_content)}")
print(f"CPP length: {len(cpp_content)}")
print(f"F90 length: {len(f90_content)}")
PYEOF

